import Foundation

extension JSONDecoder {
    /// Shared decoder for every TMDB response (snake_case keys).
    /// Dates are decoded by the models themselves (`"yyyy-MM-dd"` or empty string).
    public static var tmdb: JSONDecoder {
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return decoder
    }
}

enum TMDBDate {
    private static func calendar() -> Calendar {
        var cal = Calendar(identifier: .gregorian)
        cal.timeZone = TimeZone(secondsFromGMT: 0)!
        return cal
    }

    /// Parses `"yyyy-MM-dd"`; returns nil for empty or malformed input.
    static func parse(_ string: String?) -> Date? {
        guard let string, !string.isEmpty else { return nil }
        let formatter = DateFormatter()
        formatter.calendar = calendar()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.date(from: string)
    }

    static func year(of date: Date?) -> String? {
        guard let date else { return nil }
        return String(calendar().component(.year, from: date))
    }
}
EOF
